BEGIN;
ALTER TABLE IF EXISTS users ADD COLUMN IF NOT EXISTS tenant_id TEXT;
CREATE TABLE IF NOT EXISTS evidence_workflows (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id TEXT NOT NULL, subject_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', version INTEGER NOT NULL DEFAULT 1, analyst_id TEXT NOT NULL, reviewer_id TEXT, model_version TEXT, retention_class TEXT NOT NULL, moderation_status TEXT NOT NULL DEFAULT 'pending', watermark_policy TEXT NOT NULL DEFAULT 'required', disclosure_policy TEXT NOT NULL DEFAULT 'required', approved_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(tenant_id,idempotency_key), UNIQUE(tenant_id,subject_id,id));
CREATE TABLE IF NOT EXISTS evidence_workflow_sources (id BIGSERIAL PRIMARY KEY, tenant_id TEXT NOT NULL, subject_id TEXT NOT NULL, workflow_id UUID NOT NULL, source_uri TEXT NOT NULL, checksum TEXT NOT NULL, captured_at TIMESTAMPTZ NOT NULL, consent_or_authority TEXT NOT NULL, metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(tenant_id,workflow_id,checksum));
CREATE TABLE IF NOT EXISTS evidence_workflow_deliveries (id BIGSERIAL PRIMARY KEY, tenant_id TEXT NOT NULL, subject_id TEXT NOT NULL, workflow_id UUID NOT NULL, provider_type TEXT NOT NULL, idempotency_key TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','acknowledged','retrying','dead_letter')), attempt_count INTEGER NOT NULL DEFAULT 0, next_attempt_at TIMESTAMPTZ, receipt JSONB, last_error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(tenant_id,provider_type,idempotency_key));
CREATE TABLE IF NOT EXISTS evidence_workflow_evaluations (id BIGSERIAL PRIMARY KEY, tenant_id TEXT NOT NULL, workflow_id UUID, fixture_key TEXT NOT NULL, precision NUMERIC, recall NUMERIC, latency_ms INTEGER, failure_mode TEXT NOT NULL, bias_slice TEXT NOT NULL, expected_outcome JSONB NOT NULL, actual_outcome JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(tenant_id,fixture_key));
CREATE TABLE IF NOT EXISTS evidence_workflow_audit (id BIGSERIAL PRIMARY KEY, tenant_id TEXT NOT NULL, subject_id TEXT NOT NULL, workflow_id UUID NOT NULL, actor_id TEXT NOT NULL, action TEXT NOT NULL, from_status TEXT, to_status TEXT, record_version INTEGER NOT NULL, evidence JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_trail (id BIGSERIAL PRIMARY KEY, tenant_id TEXT NOT NULL, user_id INTEGER, action VARCHAR(120) NOT NULL, entity_type VARCHAR(80), entity_id INTEGER, details JSONB, ip_address VARCHAR(64), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_trail_tenant_created_idx ON audit_trail(tenant_id,created_at DESC);
CREATE OR REPLACE FUNCTION reject_evidence_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'evidence audit is append-only'; END $$;
DROP TRIGGER IF EXISTS evidence_audit_append_only ON evidence_workflow_audit;
CREATE TRIGGER evidence_audit_append_only BEFORE UPDATE OR DELETE ON evidence_workflow_audit FOR EACH ROW EXECUTE FUNCTION reject_evidence_audit_mutation();
DROP TRIGGER IF EXISTS audit_trail_append_only ON audit_trail;
CREATE TRIGGER audit_trail_append_only BEFORE UPDATE OR DELETE ON audit_trail FOR EACH ROW EXECUTE FUNCTION reject_evidence_audit_mutation();
COMMIT;
